/// <summary>
/// MET_PaymPlusJournalPostAndTransfer
/// Bug 81475: Payment Confirmation File Not Posting
/// </summary>
class METVendPaymReconciliationPost extends VendPaymReconciliationPost
{
}

Method.Source:
    /// <summary>
    /// Updated out of the box method to do post and transfer instead of post
    /// </summary>
    /// <param name = "_createdJournals"></param>
    public void postNewJournals(RecordSortedList _createdJournals = this.createdJournals())
    {
        Args args;
        LedgerJournalTable ledgerJournalTable;

        args = new Args();
        args.caller(this);

        if (_createdJournals.first(ledgerJournalTable))
        {
            do
            {
                setPrefix(strFmt("@SYS28641", ledgerJournalTable.JournalName, ledgerJournalTable.JournalNum));
                args.record(ledgerJournalTable);

                // Bug 81475: Payment Confirmation File Not Posting
                // Change journal posting to post and transfer so that error lines don't block the posting
                //new MenuFunction(menuitemActionStr(LedgerJourPostLJTransVendPaym), MenuItemType::Action).run(args);
                new MenuFunction(menuitemActionStr(LedgerJourPostTrLJTransVendPaym), MenuItemType::Action).run(args);
            }
            while (_createdJournals.next(ledgerJournalTable));
        }
    }
